let _REGISTRY_WITH_BYTES_CACHE = null;

/**
 * 获取「含 bytes + meta」的完整模板注册表（懒初始化，首次调用才构造 Uint8Array）。
 *
 * ⚠️  严格调用约束
 *     ✅ 允许：只在 method（如 _doGenerateContract）内部调用，生成 Excel 用
 *     ❌ 禁止：进入 Vue template / data / computed / watch 任何链路
 *              否则 TypedArray 会被序列化，触发 setData 14MB+ 告警
 *
 * @returns {Array<{key,family,displayName,bytes:Uint8Array,meta}>} 可直接传给 buildContract
 */
export function getTemplateRegistryForBuild() {
  if (_REGISTRY_WITH_BYTES_CACHE) return _REGISTRY_WITH_BYTES_CACHE;
  _REGISTRY_WITH_BYTES_CACHE = _TPL_METAS_FULL.map(function(t) {
    var bytes;
    try { bytes = new Uint8Array(t._snap); } catch (e) { bytes = t._snap; }
    return {
      key: t.key,
      family: t.family,
      displayName: t.displayName,
      bytes: bytes,
      meta: t.meta
    };
  });
  return _REGISTRY_WITH_BYTES_CACHE;
}

/** 按 key 取单个完整模板（含 bytes），找不到返回第一个。调用约束同上 */
export function getTemplateByKeyForBuild(key) {
  var reg = getTemplateRegistryForBuild();
  for (var i = 0; i < reg.length; i++) if (reg[i].key === key) return reg[i];
  return reg[0];
}

